 async function save(kind:string,data:any){if(!canWrite()||busyRef.current)return null;busyRef.current=true;setBusy(true);try{validateRecord(kind,data);const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,data})});const d:any=await r.json();if(!r.ok)throw Error(d.error);const updated={...data,revision:d.revision};if(kind==='video'){setVideos(v=>v.some(x=>x.id===data.id)?v.map(x=>x.id===data.id?updated:x):[updated,...v]);if(detail?.id===data.id){setDetail(updated);setTranscript('');}}else{setExperiments(v=>v.some(x=>x.id===data.id)?v.map(x=>x.id===data.id?updated:x):[updated,...v]);experimentBaseline.current=JSON.stringify(updated);if(data.hypothesis===script)setScriptSaved(script);}notify('已保存到研究站','success');return updated;}catch(e){notify((e as Error).message,'error');return null;}finally{busyRef.current=false;setBusy(false);}}
