 async function readBackup(file:File|undefined){if(!file)return;if(file.size>5_000_000){notify('备份文件超过 5 MB，请分批导入。','error');if(backupInput.current)backupInput.current.value='';return;}try{const parsed=parseResearchBackup(await file.text());setBackup(parsed);setReplaceExisting(false);setRestoreProgress('');}catch(e){notify((e as Error).message,'error');}finally{if(backupInput.current)backupInput.current.value='';}}
 const backupConflicts=backup?[...backup.videos.filter(v=>videos.some(x=>x.id===v.id)).map(v=>v.title),...backup.experiments.filter(e=>experiments.some(x=>x.id===e.id)).map(e=>e.title)]:[];
 async function restoreBackup(){if(!backup||!canWrite()||restoring)return;setRestoring(true);const work=[...backup.videos.map(data=>({kind:'video',data,current:videos.find(v=>v.id===data.id)})),...backup.experiments.map(data=>({kind:'experiment',data,current:experiments.find(e=>e.id===data.id)}))].filter(x=>replaceExisting||!x.current);let completed=0;try{for(const item of work){setRestoreProgress(`正在恢复 ${completed+1} / ${work.length}：${item.data.title}`);const data={...item.data,revision:item.current?.revision||0};const saved=await save(item.kind,data);if(!saved){setRestoreProgress(`已恢复 ${completed} 条，剩余 ${work.length-completed} 条未完成。请修正资料后重试；已保存记录保留。`);return;}completed++;}setRestoreProgress(`已恢复 ${completed} 条资料。${replaceExisting?'已按预览替换同 ID 记录。':`跳过 ${backupConflicts.length} 条已有记录。`}`);notify(`备份恢复完成：${completed} 条资料已保存`,'success');setBackup(null);}finally{setRestoring(false);}}
